// npm run gen:ipc — generate src/ui/ipc.ts from the frozen contract
// .agent/schemas/ipc-commands.json (coordinator-owned, CONTRACTS.md §Native).
// `npm run check` fails on drift between the frozen contract, commands.rs
// handler names, and this generated file. Do not hand-edit the output.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  readFileSync(path.join(rootDir, ".agent", "schemas", "ipc-commands.json"), "utf8")
);

const seen = new Map();
for (const cmd of contract.commands) {
  for (const [name, shape] of Object.entries(cmd.types ?? {})) {
    if (!seen.has(name)) seen.set(name, shape);
  }
}

const typeDecls = [...seen.entries()]
  .map(([name, shape]) => `export interface ${name} ${shape};`)
  .join("\n");

function tsArgs(cmd) {
  return Object.entries(cmd.args)
    .map(([k, v]) => `${k}: ${v}`)
    .join("; ");
}

function invokeArgs(cmd) {
  const keys = Object.keys(cmd.args);
  if (keys.length === 1 && keys[0] !== "input") {
    return `{ ${keys[0]} }`;
  }
  return "{ input }";
}

function fnParams(cmd) {
  const keys = Object.keys(cmd.args);
  if (keys.length === 1 && keys[0] !== "input") {
    return `${keys[0]}: ${cmd.args[keys[0]]}`;
  }
  return `input: ${cmd.args.input}`;
}

const fns = contract.commands
  .map(
    (cmd) => `export function ${cmd.name}(${fnParams(cmd)}): Promise<{ mode: BridgeMode; data: ${cmd.returns} }> {
  return bridgeInvoke<${cmd.returns}>("${cmd.name}", ${invokeArgs(cmd)} as Record<string, unknown>);
}`
  )
  .join("\n\n");

const out = `// GENERATED by npm run gen:ipc from .agent/schemas/ipc-commands.json
// (contract v${contract.contract_version}, frozen ${contract.frozen_at}). Do not edit.
import { bridgeInvoke, type BridgeMode } from "./bridge.ts";

${typeDecls}

${fns}
`;

const outPath = path.join(rootDir, "src", "ui", "ipc.ts");
writeFileSync(outPath, out);
console.log(`gen:ipc wrote ${path.relative(rootDir, outPath)} (${contract.commands.length} commands)`);
